// ── forbidden.ts ──────────────────────────────────────────────────────────────
export const FORBIDDEN_PATHS = new Set([
  "package.json",
  "package-lock.json",
  "app.json",
  "tsconfig.json",
  "tsconfig.base.json",
  "babel.config.js",
  "babel.config.ts",
  "metro.config.js",
  "metro.config.ts",
  "expo.config.js",
  "expo.config.ts",
  // NativeWind snapshot infra — baked once, never repaired.
  "tailwind.config.js",
  "tailwind.config.ts",
  "global.css",
  "nativewind-env.d.ts",
  "postcss.config.js",
]);

/** Returns true if the given file path is forbidden (must not be written). */
export function isForbiddenPath(filePath) {
  const normalized = filePath.replace(/^\.\//, "");
  return FORBIDDEN_PATHS.has(normalized);
}

// ── overlay.ts ────────────────────────────────────────────────────────────────
/**
 * Returns true if the HTML response looks like a Metro bundler error overlay
 * rather than a healthy bundle. Checks only unambiguous error-specific markers
 * that do NOT appear in healthy bundles.
 */
export function looksLikeMetroOverlay(html) {
  const markers = [
    // Metro bundler error — appears in "Unable to resolve module" pages
    "Unable to resolve module",
    // Metro compile-time failure
    "Bundling failed",
    // RN app registration failure
    "Application has not been registered",
    // Same failure, alternate phrasing
    "hasn't been registered",
    // React Native LogBox error overlay testid (error state only)
    'data-testid="logbox-overlay"',
    // Metro's own error HTML page title (only rendered on error, not in bundles)
    "<title>Metro Bundler</title>",
  ];
  const lower = html.toLowerCase();
  for (const marker of markers) {
    if (lower.includes(marker.toLowerCase())) return true;
  }
  return false;
}

// ── decision.ts ───────────────────────────────────────────────────────────────
/** Maximum total attempts (0-based attempts 0, 1, 2 → 3 tries). */
export const MAX_ATTEMPTS = 3;

/** Tolerate up to this many consecutive spurious Daytona NotFound responses. */
export const MAX_NOT_FOUND_TOLERANCE = 2;

/** Heartbeat age past which the sandbox is presumed dead. */
export const HEARTBEAT_STALE_MS = 60_000;

export function decide(input) {
  const {
    jobStatus,
    heartbeatAgeMs,
    attempt,
    sandboxState,
    isEdit,
    budgetExhausted,
    turnLimitReached,
    notFoundCount,
  } = input;

  // Completed successfully.
  if (jobStatus === "complete") return "complete";

  // Budget or turn limit exhausted — terminal failure.
  if (budgetExhausted || turnLimitReached) return "fail";

  // Tolerate spurious Daytona NotFound up to MAX_NOT_FOUND_TOLERANCE times.
  if (jobStatus === "not-found") {
    if (notFoundCount <= MAX_NOT_FOUND_TOLERANCE) return "continue";
    // Too many consecutive NotFound → treat death.
    return attempt < MAX_ATTEMPTS - 1
      ? isEdit && attempt === 0
        ? "retry-git-reset"
        : "retry-recreate"
      : "fail";
  }

  // Runner reported failure.
  if (jobStatus === "failed") {
    if (attempt < MAX_ATTEMPTS - 1) {
      return isEdit && attempt === 0 ? "retry-git-reset" : "retry-recreate";
    }
    return "fail";
  }

  // Sandbox stopped = dead.
  if (sandboxState === "stopped") {
    if (attempt < MAX_ATTEMPTS - 1) {
      return isEdit && attempt === 0 ? "retry-git-reset" : "retry-recreate";
    }
    return "fail";
  }

  // Heartbeat stale = presumed dead.
  if (heartbeatAgeMs > HEARTBEAT_STALE_MS) {
    if (attempt < MAX_ATTEMPTS - 1) {
      return isEdit && attempt === 0 ? "retry-git-reset" : "retry-recreate";
    }
    return "fail";
  }

  // Job is running, everything looks healthy.
  return "continue";
}

// ── report.ts ─────────────────────────────────────────────────────────────────
function toNumber(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function toStringArray(v) {
  if (!Array.isArray(v)) return [];
  return v.filter((x) => typeof x === "string");
}

export function parseRunnerReport(raw) {
  if (typeof raw !== "object" || raw === null) {
    return { valid: false, error: "report must be a non-null object" };
  }
  const obj = raw;

  const ok = typeof obj["ok"] === "boolean" ? obj["ok"] : false;
  const summary = typeof obj["summary"] === "string" ? obj["summary"] : "";
  const entryScreens = toStringArray(obj["entryScreens"]);
  const costUsd = toNumber(obj["costUsd"]);

  const rawUsage =
    typeof obj["usage"] === "object" && obj["usage"] !== null
      ? (obj["usage"])
      : {};

  const usage = {
    inputTokens: toNumber(rawUsage["inputTokens"]),
    outputTokens: toNumber(rawUsage["outputTokens"]),
    cacheReadTokens: toNumber(rawUsage["cacheReadTokens"]),
    cacheWriteTokens: toNumber(rawUsage["cacheWriteTokens"]),
  };

  return {
    valid: true,
    report: { ok, summary, entryScreens, costUsd, usage },
  };
}

// ── token.ts ──────────────────────────────────────────────────────────────────
const ALGO = { name: "HMAC", hash: "SHA-256" };

async function importKey(secret) {
  const enc = new TextEncoder();
  return crypto.subtle.importKey("raw", enc.encode(secret), ALGO, false, [
    "sign",
    "verify",
  ]);
}

function toBase64url(buf) {
  const bytes = buf instanceof Uint8Array ? buf : new Uint8Array(buf);
  return btoa(String.fromCharCode(...bytes))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

function fromBase64url(s) {
  const b64 = s.replace(/-/g, "+").replace(/_/g, "/");
  const bin = atob(b64);
  return Uint8Array.from(bin, (c) => c.charCodeAt(0)).buffer;
}

/** Sign a payload and return a compact token: base64url(payload).base64url(sig) */
export async function signToken(
  payload,
  secret,
) {
  const enc = new TextEncoder();
  const payloadB64 = toBase64url(enc.encode(JSON.stringify(payload)));
  const key = await importKey(secret);
  const sig = await crypto.subtle.sign(ALGO, key, enc.encode(payloadB64));
  return `${payloadB64}.${toBase64url(sig)}`;
}

/** Verify a token. Returns the payload if valid, or an error reason. */
export async function verifyToken(
  token,
  secret,
  now = Date.now(),
) {
  const parts = token.split(".");
  if (parts.length !== 2) {
    return { valid: false, reason: "malformed token: expected 2 parts" };
  }
  const [payloadB64, sigB64] = parts;

  const key = await importKey(secret);
  const enc = new TextEncoder();
  let isValid ;
  try {
    isValid = await crypto.subtle.verify(
      ALGO,
      key,
      fromBase64url(sigB64),
      enc.encode(payloadB64),
    );
  } catch {
    return { valid: false, reason: "signature verification error" };
  }

  if (!isValid) return { valid: false, reason: "signature mismatch" };

  let payload ;
  try {
    payload = JSON.parse(new TextDecoder().decode(fromBase64url(payloadB64)));
  } catch {
    return { valid: false, reason: "payload JSON parse error" };
  }

  if (
    typeof payload !== "object" ||
    payload === null ||
    typeof (payload)["versionId"] !== "string" ||
    typeof (payload)["exp"] !== "number"
  ) {
    return { valid: false, reason: "payload shape invalid" };
  }

  const typed = payload;
  if (now > typed.exp) {
    return { valid: false, reason: "token expired" };
  }

  return { valid: true, payload: typed };
}

// ── tsc follow-up turn builder ────────────────────────────────────────────────
function buildTscFollowUpTurn(errorBlock) {
  return [
    "TypeScript errors were found after your changes. Please fix them.",
    "",
    "```",
    errorBlock,
    "```",
    "",
    "Run `npx tsc --noEmit --pretty false` after your edits to verify they are resolved.",
  ].join("\n");
}

